// truncate.pipe.ts
import { Pipe, PipeTransform } from '@angular/core';

@Pipe({ name: 'truncate' })
export class TruncatePipe implements PipeTransform {
  transform(value: string, maxLength: number = 20): string {
    if (!value) return '';
    if (value.length <= maxLength) return value;
    return value.substring(0, maxLength) + '...';
  }
}

// component.ts
export class AppComponent {
  shortText = 'Hello';
  longText = 'This is a very long string that needs truncation.';
}

// component.html
<p>{{ shortText | truncate:20 }}</p>    <!-- Hello -->
<p>{{ longText | truncate:20 }}</p>      <!-- This is a very long ... -->
<p>{{ longText | truncate:30 }}</p>      <!-- This is a very long string t... -->
